<script setup lang="ts">
import {qualityText as qt} from '../i18n'

import {defineAsyncComponent,onMounted,reactive,ref,watch} from 'vue'
import type {QualityClient} from '../client'
import {useQualityDetail} from '../useQualityDetail'
import {actions,orderStates,rectStates,time,type CheckRecord} from '../types'
const Media=defineAsyncComponent(()=>import('./QualityMedia.vue')),ActionForm=defineAsyncComponent(()=>import('./QualityActionForm.vue')),RepairForm=defineAsyncComponent(()=>import('./QualityRepairForm.vue'))
const props=defineProps<{api:QualityClient;id:string}>(),emit=defineEmits<{changed:[]}>(),vm=reactive(useQualityDetail(props.api)),repair=ref<{show:(record:CheckRecord)=>Promise<void>}>()
const reload=async()=>{await vm.load(props.id);emit('changed')}
watch(()=>props.id,()=>void vm.load(props.id));onMounted(()=>void vm.load(props.id))
</script>
<template><div class="quality-detail"><div style="margin-bottom:16px"><van-button :loading="vm.loading" @click="reload" native-type="button">{{qt('refresh')}}</van-button><van-tag v-if="vm.data" color="blue">{{orderStates[vm.data.workOrder.workOrderStatus]}}</van-tag></div><MobileNotice v-if="vm.error" type="error" :message="vm.error" show-icon /><MobileNotice v-if="vm.success" type="success" :message="vm.success" show-icon /><MobileLoading :loading="vm.loading"><template v-if="vm.data">
 <div :column="2" bordered size="small"><van-cell :title="qt('taskName')">{{vm.data.workOrder.taskName}}</van-cell><van-cell :title="qt('businessProject')">{{vm.data.workOrder.projectName}}</van-cell><van-cell :title="qt('orderNumber')">{{vm.data.workOrder.taskCode}}</van-cell><van-cell :title="qt('taskTemplate')">{{vm.data.workOrder.templateName}}</van-cell><van-cell :title="qt('generationTime')">{{time(vm.data.workOrder.scheduledTime)}}</van-cell><van-cell :title="qt('submissionTimeLimit')">{{time(vm.data.workOrder.reportDeadline)}}</van-cell><van-cell :title="qt('totalScore')">{{vm.data.workOrder.totalScore??'—'}}</van-cell><van-cell :title="qt('rating')">{{vm.data.workOrder.evaluationName||'—'}}</van-cell></div>
 <div wrap style="margin:20px 0"><van-button v-if="vm.owned.length&&vm.can('inspect')" type="primary" @click="vm.start('inspect')" native-type="button">{{qt('startInspectionRestoreDraft')}}</van-button><van-button v-if="vm.owned.length&&vm.can('reassign')" @click="vm.start('reassign')" native-type="button">{{qt('reassignInspection2')}}</van-button><van-button v-if="vm.data.workOrder.workOrderStatus===1&&vm.can('dispatch')" @click="vm.start('dispatch')" native-type="button">{{qt('administrativeAssignment')}}</van-button></div>
 <van-tabs><van-tab name="records" :title="qt('checkDetails')"><MobileCard v-for="r in vm.data.records" :key="r.id" :title="r.checkContentName" size="small" style="margin-bottom:12px"><template #extra><van-tag :color="r.recordStatus===2?(r.isQualified?'green':'red'):'orange'">{{r.recordStatus===2?(r.isQualified?qt('qualified'):qt('unqualified')):r.recordStatus===3?qt('overdue'):qt('pendingInspection')}}</van-tag></template><p>{{r.subjectParentName}} / {{r.subjectName}} {{qt('inspector')}}{{r.executorName}}</p><p style="white-space:pre-wrap">{{r.checkRequirement}}</p><p v-if="r.deductionStandard">{{qt('deductionRule2')}}{{r.deductionStandard}}</p><p v-if="r.recordStatus===2">{{qt('score')}} {{r.score}} / {{r.originalScore}} · {{r.checkResult||'—'}}</p><p>{{qt('photoRequirements2')}}{{r.photoRequirement}}</p><Media :api="api" :ids="r.photoIds||[]" readonly /><div v-if="r.rectificationPhotoIds?.length"><p>{{qt('rectificationPhotos')}}</p><Media :api="api" :ids="r.rectificationPhotoIds" readonly /></div><van-button v-if="r.isQualified===0&&vm.can('transferRepair')" plain @click="repair?.show(r)" native-type="button">{{r.repairOrderId?qt('viewLinkedRepair'):qt('createRepair')}}</van-button></MobileCard></van-tab>
 <van-tab name="rectifications" :title="qt('rectificationAndReview')+vm.data.rectifications.length+'）'"><van-empty v-if="!vm.data.rectifications.length" :description="qt('noRectificationTasks')" /><MobileCard v-for="rect in vm.data.rectifications" :key="rect.id" :title="rectStates[rect.rectificationStatus]" size="small" style="margin-bottom:12px"><p>{{qt('reviewer')}}{{rect.reviewerName}}</p><p>{{qt('issue2')}}{{rect.recordIds.map(id=>vm.record(id)?.checkContentName).join('、')}}</p><p v-if="rect.rectificationDesc">{{qt('rectificationDescription2')}}{{rect.rectificationDesc}}</p><MobileNotice v-if="rect.rejectReason" :message="qt('rejectionReason2')+rect.rejectReason" type="warning" show-icon /><div wrap><template v-if="vm.editableRects.some(r=>r.id===rect.id)&&vm.can('rectify')"><van-button type="primary" @click="vm.start('submit',rect.id)" native-type="button">{{qt('submitRectification')}}</van-button><van-button @click="vm.start('rectReassign',rect.id)" native-type="button">{{qt('reassignRectification2')}}</van-button></template><template v-if="vm.reviewable.some(r=>r.id===rect.id)&&vm.can('review')"><van-button type="primary" @click="vm.start('pass',rect.id)" native-type="button">{{qt('reviewPassed')}}</van-button><van-button type="danger" @click="vm.start('reject',rect.id)" native-type="button">{{qt('reject')}}</van-button></template></div></MobileCard></van-tab>
 <van-tab name="history" :title="qt('activityLog')"><van-steps direction="vertical" :active="999"><van-step v-for="log in vm.data.history" :key="log.id"><strong>{{actions[log.action]||log.action}}</strong> · {{log.operatorName}}<p>{{time(log.createTime)}}</p><p v-if="log.details.description">{{log.details.description}}</p></van-step></van-steps></van-tab></van-tabs>
 </template><van-empty v-else-if="!vm.loading&&!vm.error" :description="qt('orderNotFound')" /></MobileLoading><ActionForm :api="api" :vm="vm" /><RepairForm ref="repair" :api="api" @changed="reload" /></div></template>
